import{_ as r,a0 as p,w as l,s as i,ao as g,I as a,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"命令列星期二 ——  第一篇 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二 ——  第一篇 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二 ——  第一篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二 ——  第一篇 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140612 Command Line Tuesdays--Part One","title":"命令列星期二 ——  第一篇","tag":"201406","desc":""},"relativePath":"201406/20140612 Command Line Tuesdays--Part One.md","filePath":"[post].md"}'),m={name:"201406/20140612 Command Line Tuesdays--Part One.md"};function d(u,t,h,f,T,x){const s=p("Link");return l(),i("div",null,[t[11]||(t[11]=g('<h1 id="命令列星期二-——-第一篇" tabindex="-1">命令列星期二 —— 第一篇 <a class="header-anchor" href="#命令列星期二-——-第一篇" aria-label="Permalink to “命令列星期二 ——  第一篇”">​</a></h1><p>極客們，我們又回來了！真抱歉讓你們久等了，但我保證，我們又迴歸正軌了。我們滿懷熱情與大家相約，讓我們激情燃燒，尋找刺激吧:)</p><p>現在，整個的想法已經在之前的開場白中告訴你們了，所以現在讓我們來乾點正事吧。就像肖茨先生書裏講得那樣，我們需要來了解一下shell是個什麼東西，終端模擬器又是個什麼東西，因為我們要在這裏頭幹活。</p><p>肖茨在他的書中寫道，shell實際上是當我們談論命令列時所談論的東西。shell基本上一個程序，它將你敲擊鍵盤的動作傳遞給計算機；它也是某種形式的翻譯器，將你所講的東西翻譯給計算機聽。在這世界上活着的shell真是五花八門，但是活得最好的要數<strong>bash</strong>了，它在GNU/Linux中隨處可見。我們也叫它Bourne Again Shell，這是一個精巧的雙關語，因為自從Bourne先生創造了它的祖先<strong>sh</strong>後，Brian Fox又把它重寫成為一個自由的sh替代品。啊哈！GUN人和他們的幽默，真的很精明。😃</p><p><img src="http://paste.opensuse.org/images/54535272.jpg" alt=""></p><p>接下來我所需要，是一個讓我們能和shell交互的東西，它就是終端模擬器。每個Linux發行版都自帶了一個，至於長什麼樣就得看你使用的桌面環境了，可能是KDE的<strong>Konsole</strong>，也可能是Gnome的<strong>Gnome terminal</strong>等等。肖茨先生説了，你可以挖掘出你所偏愛的一個，但是大部分時間我還是用桌面環境給我提供的那個吧。</p><p>現在來發動你的終端。打開後，你會見到一行字，這行字告訴你用户名和機器的主機名，它叫作shell提示符。它告訴你它準備好了，你可以輸入命令了。讓我們來隨便玩玩，隨便輸入點什麼東西進去，然後敲回車看看。</p><p>呵呵，還記開篇我們講過，我們需要像學詩歌一樣來學習命令嗎？記得就好，隨意亂來可幹不了啥事。</p><p>現在，按那個上箭頭，你會發現命令又回來了。這是啥魔法？你鍵盤上的上箭頭用來取出歷史命令。終端會保存總計500個你輸入過的命令，所以別一次又一次地重複敲它們了，你可以用上/下箭頭來查找它們。左右箭頭用來在指定行中移動光標，這樣你就可以在文本中編輯或者插入了。另外注意，想用<strong>ctrl+v</strong>來粘貼文本是不行的。你可以在某個地方將它設置成快捷鍵，但是它常常不是那麼回事。檢查你的模擬器的快捷鍵！（在Konsole中，它位於設置 &gt; 配置快捷鍵）</p><p>現在，為了我們不再被‘命令找不到’抽一巴掌，讓我們試試一些簡單的。敲個<strong>date</strong>來試試。（是的，我不知道有這麼個命令，這真着實讓我興奮了一把）😃</p><p><img src="http://paste.opensuse.org/images/7123365.png" alt=""></p><p>你又來了。當你能打開終端並輸入date命令來查看日期時，為什麼在時鐘中看看內建日曆會讓你不勝其煩 😃 只是開個玩笑。就像肖茨書裏寫的那樣，它確實是個簡單的命令，更有用也更復雜的命令會在以後介紹。跟date相關的命令是cal - 它會顯示當前月的日曆。</p><p>你也可以試試<strong>df</strong>，它會列出你驅動器上的空閒空間。</p><p><img src="http://paste.opensuse.org/images/44662534.png" alt=""></p><p>或者試試<strong>free</strong>來顯示空閒內存：</p><p><img src="http://paste.opensuse.org/images/44548116.png" alt=""></p><p>如果你已經跟上了敲擊鍵盤的節奏，你可以輸入<strong>exit</strong>命令來關閉終端模擬器了，而不是去點擊那個x了。</p><p>嗯，本週我們就到此為止吧，免得有太多的要學的東西來佔據你緊巴巴的日程了。下面來個小結（你可以把結論寫下來，做個備份吧），在這一篇中，我們學習了：</p><ul><li>什麼是shell</li><li>我們需要用什麼來和shell交流（終端模擬器）</li><li>使用光標按鈕來駕馭終端命令以及退出終端</li></ul><p>四個簡單的命令：</p><ul><li><strong>date</strong> – 顯示當前日期</li><li><strong>cal</strong> – 顯示當前月份的日曆</li><li><strong>df</strong> – shows the amount of free space on your hard drives</li><li><strong>free</strong> – amount of free memory</li></ul><h3 id="下週二我們將會做什麼呢" tabindex="-1">下週二我們將會做什麼呢？ <a class="header-anchor" href="#下週二我們將會做什麼呢" aria-label="Permalink to “下週二我們將會做什麼呢？”">​</a></h3><p>我們會學習在文件系統中導航（bin、etc等等這所有的文件夾都是些什麼東西？它們用來幹什麼？怎樣通過終端來瀏覽它們）。到那時……</p><h3 id="你就有得樂了" tabindex="-1">你就有得樂了！ <a class="header-anchor" href="#你就有得樂了" aria-label="Permalink to “你就有得樂了！”">​</a></h3><p><img src="http://paste.opensuse.org/images/40949666.jpg" alt=""></p><hr>',26)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"https://news.opensuse.org/2014/06/10/command-line-tuesdays-part-one/"},{default:o(()=>[...t[0]||(t[0]=[e("https://news.opensuse.org/2014/06/10/command-line-tuesdays-part-one/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(s,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const _=r(m,[["render",d]]);export{P as __pageData,_ as default};
